def parse_range(s):
    if '-' in s:
        parts = s.split('-')
        if len(parts) != 2:
            raise ValueError("Invalid range")
        try:
            start = int(parts[0])
            end = int(parts[1])
        except ValueError:
            raise ValueError("Invalid range")
        if start > end:
            raise ValueError("Invalid range")
        return list(range(start, end + 1))
    else:
        try:
            n = int(s)
        except ValueError:
            raise ValueError("Invalid range")
        return [n]
